const assert=require('node:assert/strict');const fs=require('node:fs/promises');const path=require('node:path');const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');
const base=process.argv[2]||'http://127.0.0.1:4400';const out=path.resolve(process.argv[3]||'docs/product-completion/qa-codecs-independent-2026-10-04');
const report={base,started:new Date().toISOString(),errors:[],checks:[],screenshots:[]};
(async()=>{await fs.mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const page=await browser.newPage({acceptDownloads:true,viewport:{width:1440,height:1000}});page.on('pageerror',e=>report.errors.push(e.message));
async function visit(slug){await page.goto(base+'/'+slug,{waitUntil:'domcontentloaded',timeout:120000});await page.getByRole('button',{name:/Switch to (dark|light) mode/}).waitFor();}
async function download(expected,name){const p=page.waitForEvent('download');await page.getByRole('button',{name:'Download output',exact:true}).click();const d=await p;const file=path.join(out,name);await d.saveAs(file);assert.deepEqual(await fs.readFile(file),Buffer.from(expected));return file;}
async function shot(name){await page.screenshot({path:path.join(out,name+'.png'),fullPage:true});report.screenshots.push(name+'.png');}
try{const text=' \uFEFFनमस्ते 💾 /?&=+ \n';await visit('base64-encode');await page.getByLabel('Text to encode',{exact:true}).fill(text);await page.getByRole('button',{name:'Encode to Base64',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();const expected=Buffer.from(text).toString('base64');assert.equal(await page.getByLabel('Base64 output',{exact:true}).inputValue(),expected);await download(expected,'unicode-base64.txt');await page.getByLabel('Text to encode',{exact:true}).fill('changed');assert.equal(await page.getByRole('button',{name:'Download output',exact:true}).count(),0);report.checks.push('Base64 Unicode+BOM+whitespace exact download; changing input invalidates result');
 const binary=Buffer.from([0,255,128,10,13,65]);await page.getByRole('button',{name:'File',exact:true}).click();await page.locator('input[type=file]').setInputFiles({name:'binary.bin',mimeType:'application/octet-stream',buffer:binary});await page.getByRole('button',{name:'Encode to Base64',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();await download(binary.toString('base64'),'binary-base64.txt');report.checks.push('Base64 raw binary file byte-exact encoding');
 await visit('base64-decode');await page.getByLabel('Base64 input',{exact:true}).fill(binary.toString('base64'));await page.getByRole('button',{name:'Decode Base64',exact:true}).click();await page.getByText('This output contains binary data',{exact:false}).waitFor();assert.equal(await page.getByRole('button',{name:'Copy output',exact:true}).count(),0);await download(binary,'decoded-binary.bin');await page.getByLabel('Base64 input',{exact:true}).fill('%%%');await page.getByRole('button',{name:'Decode Base64',exact:true}).click();await page.getByRole('alert').waitFor();assert.equal(await page.getByRole('button',{name:'Download output',exact:true}).count(),0);await page.getByLabel('Base64 input',{exact:true}).fill(expected);await page.getByRole('button',{name:'Decode Base64',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();await download(Buffer.from(text),'decoded-unicode.txt');report.checks.push('Base64 binary decoding and malformed→Unicode recovery exact downloads');
 await visit('url-decode');await page.getByLabel('URL-encoded input',{exact:true}).fill('A+B%2BC%20D');await page.getByRole('button',{name:'URL Decode',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();await download('A+B+C D','plus-literal.txt');await page.getByRole('checkbox').check();assert.equal(await page.getByRole('button',{name:'Download output',exact:true}).count(),0);await page.getByRole('button',{name:'URL Decode',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();await download('A B+C D','plus-as-space.txt');report.checks.push('URL plus option invalidates result; literal + and %2B semantics exact');
 await page.waitForTimeout(200);
 report.buttonStyles=await page.getByRole('button',{name:/Download output|Copy output/}).evaluateAll(es=>es.map(e=>({text:e.textContent,disabled:e.disabled,disabledSelector:e.matches(':disabled'),style:{opacity:getComputedStyle(e).opacity,color:getComputedStyle(e).color,backgroundColor:getComputedStyle(e).backgroundColor},ancestorOpacity:[...function*(n){while(n){yield n;n=n.parentElement;}}(e.parentElement)].map(n=>({tag:n.tagName,opacity:getComputedStyle(n).opacity}))})));
 for(const width of [375,768,1440]){await page.setViewportSize({width,height:1000});await shot('url-decode-result-'+width);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}await page.getByRole('button',{name:'Switch to dark mode'}).click();await shot('url-decode-result-dark');await page.getByRole('button',{name:'Reset all input and output',exact:true}).click();assert.equal(await page.getByLabel('URL-encoded input',{exact:true}).inputValue(),'');report.checks.push('Result no horizontal overflow375/768/1440; dark screenshot and reset');
 await visit('url-encode');await page.getByRole('button',{name:'File',exact:true}).click();const large='a '.repeat(550000);await page.locator('input[type=file]').setInputFiles({name:'large.txt',mimeType:'text/plain',buffer:Buffer.from(large)});await page.waitForFunction(()=>document.querySelector('textarea')?.readOnly===true);assert.equal((await page.getByLabel('Text to encode',{exact:true}).inputValue()).length,100000);await page.getByRole('button',{name:'URL Encode',exact:true}).click();await page.getByRole('button',{name:'Download output',exact:true}).waitFor();await download(encodeURIComponent(large),'large-url-encoded.txt');report.checks.push('1.1million-character file:100k readonly preview; exact2.2MB full output');assert.deepEqual(report.errors,[]);report.status='passed';
}catch(e){report.status='failed';report.failure=e.message;report.text=await page.locator('body').innerText().catch(()=> '');await shot('failure').catch(()=>{});process.exitCode=1;}finally{report.finished=new Date().toISOString();await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
